import { jwtVerify, createRemoteJWKSet } from 'jose'

const JWKS = createRemoteJWKSet(new URL(`https://${TIME}.cloudflareaccess.com/cdn-cgi/access/certs`))

export async function usuarioDoAccess(req: Request) {
  const email = req.headers.get('cf-access-authenticated-user-email')
  const token = req.headers.get('cf-access-jwt-assertion')
  if (!email || !token) return null
  const { payload } = await jwtVerify(token, JWKS, { issuer: `https://${TIME}.cloudflareaccess.com`, audience: AUD })
  return payload.email === email ? email : null
}
